const item = $input.first().json || {};
const b = item.body || item;

// só eventos de mensagem nova (updates/edit ficam pra depois)
if (b.event !== 'messages.upsert') return [];

const inst = b.instance || '';
const d = b.data || {};
const key = d.key || {};
const remoteJid = key.remoteJid || '';
const alt = key.remoteJidAlt || '';

// só 1:1 (descarta grupos @g.us e sem jid)
if (!remoteJid.endsWith('@s.whatsapp.net') && !remoteJid.endsWith('@lid')) return [];
if (key.participant && key.participant !== '') return [];

// canonicaliza: prefere o número via remoteJidAlt (mesma regra da captação)
const jid = (alt && alt.endsWith('@s.whatsapp.net')) ? alt : remoteJid;
const phone = jid.endsWith('@s.whatsapp.net') ? jid.replace('@s.whatsapp.net', '') : null;

const fromMe = !!key.fromMe;

// nome só de mensagem RECEBIDA (mensagem nossa traz o nome da própria sessão)
let pushName = fromMe ? null : d.pushName;
if (pushName === 'Você' || /^[0-9]+$/.test(pushName || '')) pushName = null;

// extrai o body (mesmo CASE da captação)
const msg = d.message || {};
let body = null;
if (msg.audioMessage) body = '[audio]';
else if (msg.imageMessage) body = msg.imageMessage.caption || '[imagem]';
else if (msg.videoMessage) body = msg.videoMessage.caption || '[video]';
else if (msg.stickerMessage) body = '[figurinha]';
else if (msg.documentMessage) body = msg.documentMessage.caption || '[documento]';
else if (msg.locationMessage) body = '[localizacao]';
else if (msg.reactionMessage) body = '[reacao]';
else if (msg.contactMessage) body = msg.contactMessage.displayName || '[contato]';
else {
  const tmpl = msg.templateMessage && msg.templateMessage.hydratedTemplate;
  body = msg.conversation
    || (msg.extendedTextMessage && msg.extendedTextMessage.text)
    || (tmpl && (tmpl.hydratedContentText || tmpl.title))
    || null;
}

// descarta sem conteúdo real (status/ack vêm como '.' ou vazio)
if (!body || body.trim() === '' || body.trim() === '.') return [];

const tsSec = d.messageTimestamp;
const ts = tsSec ? new Date(tsSec * 1000).toISOString() : null;
if (!ts) return [];

const msgId = key.id || (tsSec + '_' + (body || ''));

return [{
  json: {
    p_instance_name: inst,
    p_remote_jid: jid,
    p_contact_name: pushName,
    p_phone: phone,
    p_ts: ts,
    p_from_me: fromMe,
    p_body: body,
    p_msg_id: msgId,
  },
}];
